#!/bin/sh
# Writes deploy/compose/.env with fresh random passwords, once. Re-running it
# never overwrites an existing file.
#
# Usage: ./init-env.sh [path]   (default: .env next to this script)
set -eu

target="${1:-$(dirname "$0")/.env}"
if [ -e "$target" ]; then
  echo "init-env: $target already exists; leaving it alone"
  exit 0
fi

# Hex keeps the values safe to embed in DATABASE_URL without URL-encoding.
rand() { od -An -tx1 -N24 /dev/urandom | tr -d ' \n'; }

umask 077
cat >"$target" <<EOF
# Generated by init-env.sh. Keep this file private; it is ignored by git.
POSTGRES_PASSWORD=$(rand)
MINIO_ROOT_PASSWORD=$(rand)
ASPEN_S3_SECRET_KEY=$(rand)
EOF
echo "init-env: wrote $target"
